{
  "requested_output": "Actual profit and loss, broken out by legal entity and by calendar month.",
  "scope": null,
  "required_knowledge": [
    {
      "kind": "object",
      "name": "journal",
      "of_object": null,
      "why": "Actuals are summed from the transactional ledger of record. If the wrong table plays this part, every figure in the answer is wrong while looking plausible."
    },
    {
      "kind": "field",
      "name": "amount_local",
      "of_object": "journal",
      "why": "This is the number that gets summed. Reading the wrong amount column silently produces a P&L in the wrong currency or the wrong sign."
    },
    {
      "kind": "field",
      "name": "entity",
      "of_object": "journal",
      "why": "The answer must be broken out by legal entity, so each posting has to be attributable to one."
    },
    {
      "kind": "field",
      "name": "period",
      "of_object": "journal",
      "why": "The answer must be broken out by month. Without a trustworthy period column, postings land in the wrong month."
    },
    {
      "kind": "field",
      "name": "account",
      "of_object": "journal",
      "why": "A P&L contains only profit-and-loss accounts. Without the account on each posting, balance-sheet movements cannot be excluded."
    },
    {
      "kind": "rule",
      "name": "which accounts are profit and loss",
      "of_object": null,
      "why": "Nothing in the column layout says which accounts belong in a P&L rather than a balance sheet. Guessing this inflates or deflates every line."
    },
    {
      "kind": "rule",
      "name": "sign convention for income and expense",
      "of_object": null,
      "why": "Whether income is stored negative or positive decides whether the result is a profit or a loss of the same magnitude. The data cannot reveal the intent."
    },
    {
      "kind": "rule",
      "name": "month cut-off for late postings",
      "of_object": null,
      "why": "A posting entered after month end may belong to the closed month or the open one. The rule is a policy, not a property of the rows."
    },
    {
      "kind": "object",
      "name": "intercompany",
      "of_object": null,
      "why": "Per-entity actuals include intercompany traffic; whether the requested figures are gross or net of it changes each entity's result."
    }
  ],
  "rationale": "A P&L by entity and month rests on one ledger, four of its fields (the amount to sum, the two break-out dimensions, and the account that decides inclusion) and three conventions the vocabulary does not contain. Accounts receivable is not listed: open items do not enter a profit and loss, so the question does not require it."
}
